/**
 * Level 8 — The Vault Locks. Ability family: logical (deductive) reasoning.
 *
 * Replaces the original Level 4 "Crumbling Vault" (120 s countdown, gambles, lasers, tremor — scored as
 * Neuroticism). The vault theme is kept; time pressure, failure states and chance are removed.
 *
 * Each lock has a 3-number code using numbers 1–6, no number used twice. Clues give, for a guess,
 * how many numbers are right AND in the right place, and how many are right but in the wrong place.
 * Every clue set was generated by search (authoring/vault.js) and is minimal: it has exactly one solution
 * and removing any clue makes it ambiguous. tests/items.test.ts re-checks this with the solver below.
 */
export interface Clue {
  guess: [number, number, number];
  rightPlace: number;
  wrongPlace: number;
}

export interface LockItem {
  id: string;
  version: number;
  practice: boolean;
  difficulty: number;
  clues: Clue[];
  answer: [number, number, number];
  hint: string;
}

const c = (g: string, p: number, w: number): Clue => ({ guess: g.split('').map(Number) as Clue['guess'], rightPlace: p, wrongPlace: w });
const a = (s: string) => s.split('').map(Number) as [number, number, number];

export const LOCK_ITEMS: LockItem[] = [
  { id: 'vl_practice', version: 1, practice: true, difficulty: 0, answer: a('236'), clues: [c('231', 2, 0), c('136', 2, 0)], hint: 'Both clues share numbers in the same places.' },
  { id: 'vl1', version: 1, practice: false, difficulty: 1, answer: a('614'), clues: [c('624', 2, 0), c('415', 1, 1)], hint: 'Compare the two clues: which place keeps the same number?' },
  { id: 'vl2', version: 1, practice: false, difficulty: 2, answer: a('652'), clues: [c('526', 0, 3), c('452', 2, 0)], hint: 'The first clue has all three numbers — just in the wrong places.' },
  { id: 'vl3', version: 1, practice: false, difficulty: 3, answer: a('154'), clues: [c('153', 2, 0), c('612', 0, 1), c('431', 0, 2)], hint: 'Start with the clue that fixes two places.' },
  { id: 'vl4', version: 1, practice: false, difficulty: 4, answer: a('164'), clues: [c('234', 1, 0), c('143', 1, 1), c('642', 0, 2)], hint: 'Find a number that appears in two clues and track where it can go.' },
  { id: 'vl5', version: 1, practice: false, difficulty: 5, answer: a('135'), clues: [c('215', 1, 1), c('326', 0, 1), c('416', 0, 1), c('562', 0, 1)], hint: 'Three clues each have exactly one right number. Which number could it be?' },
  { id: 'vl6', version: 1, practice: false, difficulty: 6, answer: a('362'), clues: [c('615', 0, 1), c('652', 1, 1), c('624', 0, 2), c('265', 1, 1)], hint: 'Use the clue with two right numbers in the wrong places first.' },
];

export function feedback(guess: readonly number[], secret: readonly number[]): [number, number] {
  let p = 0;
  let w = 0;
  for (let i = 0; i < 3; i++) {
    if (guess[i] === secret[i]) p++;
    else if (secret.includes(guess[i])) w++;
  }
  return [p, w];
}

export const ALL_CODES: [number, number, number][] = (() => {
  const out: [number, number, number][] = [];
  for (let x = 1; x <= 6; x++) for (let y = 1; y <= 6; y++) for (let z = 1; z <= 6; z++) if (x !== y && y !== z && x !== z) out.push([x, y, z]);
  return out;
})();

export function solutions(clues: readonly Clue[]): [number, number, number][] {
  return ALL_CODES.filter((s) => clues.every((cl) => {
    const [p, w] = feedback(cl.guess, s);
    return p === cl.rightPlace && w === cl.wrongPlace;
  }));
}

export const isCorrectCode = (item: LockItem, code: readonly number[]) => code.length === 3 && code.every((d, i) => d === item.answer[i]);
